import re
from typing import Union

def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenize the expression
    tokens = tokenize(expr)

    if not tokens:
        raise SyntaxError("Empty expression")

    # Parse and evaluate
    parser = Parser(tokens, env)
    result = parser.parse_expression(0)

    if parser.pos < len(parser.tokens):
        raise SyntaxError(f"Unexpected token: {parser.tokens[parser.pos]}")

    return result

def tokenize(expr: str):
    tokens = []
    i = 0
    while i < len(expr):
        # Skip whitespace
        if expr[i].isspace():
            i += 1
            continue

        # Check for operators and special characters
        if expr[i:i+2] in ('==', '!=', '<=', '>='):
            tokens.append(expr[i:i+2])
            i += 2
            continue

        if expr[i] in '()[]{}+-*/%!?&|<>=^.,':
            tokens.append(expr[i])
            i += 1
            continue

        # Check for identifiers and keywords
        if expr[i].isalpha() or expr[i] == '_':
            j = i
            while j < len(expr) and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue

        # Check for numbers (integers and floats)
        if expr[i].isdigit() or (expr[i] == '.' and i+1 < len(expr) and expr[i+1].isdigit()):
            j = i
            has_dot = False
            while j < len(expr) and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1

            # Handle cases like "2." or ".5"
            if expr[j-1] == '.':
                j -= 1

            tokens.append(expr[i:j])
            i = j
            continue

        raise SyntaxError(f"Unexpected character: {expr[i]}")

    return tokens

class Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        self.pos += 1

    def parse_expression(self, min_precedence):
        # Parse the first term
        left = self.parse_unary()

        while True:
            token = self.current_token()
            if token is None:
                break

            # Check precedence and associativity
            if token == '?':
                if min_precedence >= 1:
                    break
                self.advance()
                true_expr = self.parse_expression(1)
                if self.current_token() != ':':
                    raise SyntaxError("Expected ':' after '?'")
                self.advance()
                false_expr = self.parse_expression(0)
                # Short-circuit evaluation
                if left:
                    left = true_expr
                else:
                    left = false_expr
            elif token == '||':
                if min_precedence >= 2:
                    break
                self.advance()
                right = self.parse_expression(2)
                # Short-circuit evaluation
                if left:
                    left = 1
                else:
                    left = 1 if right else 0
            elif token == '&&':
                if min_precedence >= 2:
                    break
                self.advance()
                right = self.parse_expression(2)
                # Short-circuit evaluation
                if not left:
                    left = 0
                else:
                    left = 1 if right else 0
            elif token in ('==', '!=', '<', '<=', '>', '>='):
                if min_precedence >= 3:
                    break
                op = token
                self.advance()
                right = self.parse_expression(3)

                # Check for chained comparisons (which are not allowed)
                next_token = self.current_token()
                if next_token in ('==', '!=', '<', '<=', '>', '>='):
                    raise SyntaxError("Chained comparisons are not allowed")

                if op == '==':
                    left = 1 if left == right else 0
                elif op == '!=':
                    left = 1 if left != right else 0
                elif op == '<':
                    left = 1 if left < right else 0
                elif op == '<=':
                    left = 1 if left <= right else 0
                elif op == '>':
                    left = 1 if left > right else 0
                elif op == '>=':
                    left = 1 if left >= right else 0
            elif token == '+':
                if min_precedence >= 4:
                    break
                self.advance()
                right = self.parse_expression(4)
                left = left + right
            elif token == '-':
                if min_precedence >= 4:
                    break
                self.advance()
                right = self.parse_expression(4)
                left = left - right
            elif token == '*':
                if min_precedence >= 5:
                    break
                self.advance()
                right = self.parse_expression(5)
                left = left * right
            elif token == '/':
                if min_precedence >= 5:
                    break
                self.advance()
                right = self.parse_expression(5)
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                # Check if result is integer
                if isinstance(left, int) and isinstance(right, int) and left % right == 0:
                    left = left // right
                else:
                    left = left / right
            elif token == '%':
                if min_precedence >= 5:
                    break
                self.advance()
                right = self.parse_expression(5)
                if right == 0:
                    raise ZeroDivisionError("Modulo by zero")
                # Python semantics for modulo
                left = left % right
            elif token == '^':
