                    break
                self.advance()
                # Right-associative, so we need higher precedence for right side
                right = self.parse_expression(7)
                left = left ** right
            else:
                break

        return left

    def parse_unary(self):
        token = self.current_token()

        if token == '-':
            self.advance()
            return -self.parse_unary()
        elif token == '+':
