                i += 2
                continue

        # Check for single-character operators and punctuation
        if expr[i] in '()[]{}+-*/%!?<>=^.,':
            tokens.append(expr[i])
            i += 1
            continue

        # Check for identifiers and keywords
        if expr[i].isalpha() or expr[i] == '_':
            j = i
            while j < len(expr) and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue

        # Check for numbers (integers and floats)
        if expr[i].isdigit() or (expr[i] == '.' and i+1 < len(expr) and expr[i+1].isdigit()):
            j = i
            has_dot = False
            while j < len(expr) and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1

            # Handle cases like "2." or ".5"
            if expr[j-1] == '.' and j-1 == i:
                # Just a dot, which shouldn't happen due to the condition above
                raise SyntaxError(f"Unexpected character: {expr[i]}")

            tokens.append(expr[i:j])
            i = j
            continue

        # Handle standalone dot (like in ".5")
        if expr[i] == '.' and i+1 < len(expr) and expr[i+1].isdigit():
            j = i + 1
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue

        raise SyntaxError(f"Unexpected character: {expr[i]}")

    return tokens

class Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        self.pos += 1

    def parse_expression(self, min_precedence):
        # Parse the first term
        left = self.parse_unary()

        while True:
            token = self.current_token()
            if token is None:
                break

            # Check precedence and associativity
            if token == '?':
                if min_precedence >= 1:
                    break
                self.advance()
                true_expr = self.parse_expression(1)
                if self.current_token() != ':':
                    raise SyntaxError("Expected ':' after '?'")
                self.advance()
                false_expr = self.parse_expression(0)
                # Short-circuit evaluation
                if left:
                    left = true_expr
                else:
                    left = false_expr
            elif token == '||':
                if min_precedence >= 2:
                    break
                self.advance()
                right = self.parse_expression(2)
                # Short-circuit evaluation
                if left:
                    left = 1
                else:
                    left = 1 if right else 0
            elif token == '&&':
                if min_precedence >= 2:
                    break
                self.advance()
                right = self.parse_expression(2)
                # Short-circuit evaluation
                if not left:
                    left = 0
                else:
                    left = 1 if right else 0
            elif token in ('==', '!=', '<', '<=', '>', '>='):
                if min_precedence >= 3:
                    break
                op = token
                self.advance()
                right = self.parse_expression(3)

                # Check for chained comparisons (which are not allowed)
                next_token = self.current_token()
                if next_token in ('==', '!=', '<', '<=', '>', '>='):
                    raise SyntaxError("Chained comparisons are not allowed")

                if op == '==':
                    left = 1 if left == right else 0
                elif op == '!=':
                    left = 1 if left != right else 0
                elif op == '<':
                    left = 1 if left < right else 0
                elif op == '<=':
                    left = 1 if left <= right else 0
                elif op == '>':
                    left = 1 if left > right else 0
                elif op == '>=':
                    left = 1 if left >= right else 0
            elif token == '+':
                if min_precedence >= 4:
                    break
                self.advance()
                right = self.parse_expression(4)
                left = left + right
            elif token == '-':
                if min_precedence >= 4:
                    break
                self.advance()
                right = self.parse_expression(4)
                left = left - right
            elif token == '*':
                if min_precedence >= 5:
                    break
                self.advance()
                right = self.parse_expression(5)
                left = left * right
            elif token == '/':
                if min_precedence >= 5:
                    break
                self.advance()
                right = self.parse_expression(5)
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                # Check if result is integer
                if isinstance(left, int) and isinstance(right, int) and left % right == 0:
                    left = left // right
                else:
                    left = left / right
            elif token == '%':
                if min_precedence >= 5:
                    break
                self.advance()
                right = self.parse_expression(5)
                if right == 0:
                    raise ZeroDivisionError("Modulo by zero")
                # Python semantics for modulo
                left = left % right
            elif token == '^':
                if min_precedence >= 7:
                    break
                self.advance()
                # Right-associative, so we need higher precedence for right side
                right = self.parse_expression(7)
                left = left ** right
            else:
                break

        return left

    def parse_unary(self):
        token = self.current_token()

        if token == '-':
            self.advance()
            return -self.parse_unary()
        elif token == '+':
            self.advance()
            return self.parse_unary()
        elif token == '!':
            self.advance()
            return 1 if not self.parse_unary() else 0
        else:
            return self.parse_power()

    def parse_power(self):
        left = self.parse_atom()

        token = self.current_token()
        if token == '^':
            self.advance()
            # Right-associative, so we need higher precedence for right side
            right = self.parse_power()
            left = left ** right

        return left

    def parse_atom(self):
        token = self.current_token()

        if token is None:
            raise SyntaxError("Unexpected end of expression")

        # Handle parentheses
        if token == '(':
            self.advance()
            expr = self.parse_expression(0)
            if self.current_token() != ')':
                raise SyntaxError("Expected ')'")
            self.advance()
            return expr

        # Handle numbers (including decimals starting with .)
        if re.match(r'^\d+(\.\d*)?$', token) or re.match(r'^\.\d+$', token):
            if '.' in token:
                self.advance()
                return float(token)
            else:
                self.advance()
                return int(token)

        # Handle identifiers
        if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', token):
            self.advance()

            # Check if it's a function call
            if self.current_token() == '(':
                return self.parse_function_call(token)
            else:
                # Variable lookup
                if token not in self.env:
                    raise NameError(f"Unknown variable: {token}")
                return self.env[token]

        # Handle operators that shouldn't appear alone
        if token in ('=', '&', '|'):
            raise SyntaxError(f"Unexpected token: {token}")

        raise SyntaxError(f"Unexpected token: {token}")

    def parse_function_call(self, func_name):
        if func_name not in ('min', 'max', 'abs'):
            raise NameError(f"Unknown function: {func_name}")

        if self.current_token() != '(':
            raise SyntaxError("Expected '(' after function name")

        self.advance()  # Skip '('

        args = []
        if self.current_token() != ')':
            args.append(self.parse_expression(0))
            while self.current_token() == ',':
                self.advance()
                args.append(self.parse_expression(0))

        if self.current_token() != ')':
            raise SyntaxError("Expected ')' in function call")
        self.advance()  # Skip ')'

        # Check argument counts
        if func_name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        elif func_name == 'min':
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            return min(args)
        elif func_name == 'max':
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            return max(args)

        raise SyntaxError("Unexpected error in function call")
