import re
from functools import total_ordering
from typing import List, Optional, Tuple, Union


@total_ordering
class Version:
    def __init__(self, version_str: str):
        self.original = version_str
        self._parse(version_str)

    def _parse(self, version_str: str):
        # Remove leading 'v' or '='
        s = version_str.strip()
        if s.startswith('v') or s.startswith('='):
            s = s[1:]
        s = s.strip()

        # Regex for SemVer 2.0.0
        # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        # No leading zeros in numeric parts or numeric prerelease identifiers
        # Identifiers [0-9A-Za-z-]+, non-empty
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version: {version_str}")

        self.major = int(match.group(1))
        self.minor = int(match.group(2))
        self.patch = int(match.group(3))

        prerelease_str = match.group(4)
        if prerelease_str:
            self.prerelease = tuple(prerelease_str.split('.'))
        else:
            self.prerelease = None

        # Build metadata is ignored for ordering
        self.build = match.group(5)

    def _compare_prerelease(self, other_prerelease) -> int:
        # If both have no prerelease, they are equal
        if self.prerelease is None and other_prerelease is None:
            return 0
        # If self has no prerelease and other has prerelease, self > other
        if self.prerelease is None:
            return 1
        # If self has prerelease and other doesn't, self < other
        if other_prerelease is None:
            return -1

        # Compare prerelease identifiers
        for i in range(min(len(self.prerelease), len(other_prerelease))):
            a = self.prerelease[i]
            b = other_prerelease[i]

            # Check if both are numeric
            a_numeric = a.isdigit()
            b_numeric = b.isdigit()

            if a_numeric and b_numeric:
                # Compare numerically
                a_int = int(a)
                b_int = int(b)
                if a_int != b_int:
                    return -1 if a_int < b_int else 1
            elif a_numeric:
                # Numeric < alphanumeric
                return -1
            elif b_numeric:
                # Alphanumeric > numeric
                return 1
            else:
                # Compare lexicographically (ASCII order)
                if a != b:
                    return -1 if a < b else 1

        # If all compared identifiers are equal, shorter list is smaller
        if len(self.prerelease) < len(other_prerelease):
            return -1
        elif len(self.prerelease) > len(other_prerelease):
            return 1
        return 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented

        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # Compare prerelease
        return self._compare_prerelease(other.prerelease) < 0

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __repr__(self):
        return f"Version({self.major}.{self.minor}.{self.patch}" + \
               (f"-{','.join(self.prerelease)}" if self.prerelease else "") + \
               (f"+{self.build}" if self.build else "") + ")"


def parse(v: str) -> Version:
    return Version(v)


def _parse_partial_version(version_str: str) -> Tuple[int, int, int, bool]:
    """Parse a partial version string like '1', '1.2', '1.2.x', '1.2.*', 'X'."""
    s = version_str.strip()

    # Handle 'X' or 'x'
    if s.lower() == 'x':
        return (0, 0, 0, True)

    parts = s.split('.')

    major = 0
    minor = 0
    patch = 0
    is_partial = False

    # Parse major
    if parts[0].lower() == 'x':
        major = 0
        is_partial = True
    else:
        try:
            major = int(parts[0])
            if parts[0] != str(major) and parts[0] != '0':
                raise ValueError(f"Invalid version: {version_str}")
        except ValueError:
            raise ValueError(f"Invalid version: {version_str}")

    if len(parts) > 1:
        if parts[1].lower() == 'x' or parts[1] == '*':
            minor = 0
            is_partial = True
        else:
            try:
                minor = int(parts[1])
                if parts[1] != str(minor) and parts[1] != '0':
                    raise ValueError(f"Invalid version: {version_str}")
            except ValueError:
                raise ValueError(f"Invalid version: {version_str}")

    if len(parts) > 2:
        if parts[2].lower() == 'x' or parts[2] == '*':
            patch = 0
            is_partial = True
        else:
            try:
                patch = int(parts[2])
                if parts[2] != str(patch) and parts[2] != '0':
                    raise ValueError(f"Invalid version: {version_str}")
            except ValueError:
                raise ValueError(f"Invalid version: {version_str}")

    return (major, minor, patch, is_partial)


def _parse_version_with_optional_operator(range_str: str) -> Tuple[str, str]:
    """Extract operator and version from a range string."""
    range_str = range_str.strip()

    # Check for operators
    if range_str.startswith('>='):
        return ('>=', range_str[2:].strip())
    elif range_str.startswith('<='):
        return ('<=', range_str[2:].strip())
    elif range_str.startswith('>'):
        return ('>', range_str[1:].strip())
    elif range_str.startswith('<'):
        return ('<', range_str[1:].strip())
    elif range_str.startswith('='):
        return ('=', range_str[1:].strip())
    else:
        return ('', range_str)


def _create_comparator_from_version_and_operator(op: str, version_str: str) -> callable:
    """Create a comparator function for a version and operator."""
    # Parse the version
    try:
        version = parse(version_str)
    except ValueError:
        raise ValueError(f"Invalid version in comparator: {version_str}")

    def comparator(v: Version) -> bool:
        if op == '':
            # Exact match
            return v == version
        elif op == '=':
            return v == version
        elif op == '>':
            return v > version
        elif op == '>=':
            return v >= version
        elif op == '<':
            return v < version
        elif op == '<=':
            return v <= version
        else:
            raise ValueError(f"Invalid operator: {op}")

    return comparator


def _create_xrange_comparator(major: int, minor: int, patch: int, is_partial: bool, op: str) -> callable:
    """Create a comparator for an X-range."""
    # For partial versions, we need to handle the special cases
    if op == '':
        # Default behavior for partial versions
        if is_partial:
            # For partial versions, we use the standard behavior
            # e.g., "1.2" means >=1.2.0 <1.3.0
            if minor is not None and patch is None:
                # e.g., "1.2" -> >=1.2.0 <1.3.0
                return lambda v: v.major == major and v.minor == minor and v.patch >= 0 and v.patch < 1000000
            elif minor is None:
                # e.g., "1" -> >=1.0.0 <2.0.0
                return lambda v: v.major == major and v.minor == 0 and v.patch == 0
        else:
            # Exact match
            return lambda v: v.major == major and v.minor == minor and v.patch == patch

    # Handle operator-based ranges
    if op == '>':
        # >1.2 means >=1.3.0
        if is_partial:
            # For partial versions, increment the next non-partial part
            if minor is not None and patch is None:
                # >1.2 -> >=1.3.0
                return lambda v: v.major > major or (v.major == major and v.minor > minor) or (v.major == major and v.minor == minor and v.patch >= 0)
            elif minor is None:
                # >1 -> >=2.0.0
                return lambda v: v.major > major
        else:
            # >1.2.3 -> >=1.2.4
            return lambda v: v > parse(f"{major}.{minor}.{patch}")
    elif op == '>=':
        # >=1.2 means >=1.2.0
        if is_partial:
            if minor is not None and patch is None:
                # >=1.2 -> >=1.2.0
                return lambda v: v.major == major and v.minor == minor and v.patch >= 0
            elif minor is None:
                # >=1 -> >=1.0.0
                return lambda v: v.major == major and v.minor == 0 and v.patch == 0
        else:
            # >=1.2.3
            return lambda v: v >= parse(f"{major}.{minor}.{patch}")
    elif op == '<':
        # <1.2 means <1.2.0
        if is_partial:
            if minor is not None and patch is None:
                # <1.2 -> <1.2.0
                return lambda v: v.major < major or (v.major == major and v.minor < minor)
            elif minor is None:
                # <1 -> <1.0.0
                return lambda v: v.major < major
        else:
            # <1.2.3
            return lambda v: v < parse(f"{major}.{minor}.{patch}")
    elif op == '<=':
        # <=1.2 means <1.3.0
        if is_partial:
            if minor is not None and patch is None:
                # <=1.2 -> <1.3.0
                return lambda v: v.major < major or (v.major == major and v.minor < minor)
            elif minor is None:
                # <=1 -> <2.0.0
                return lambda v: v.major < major
        else:
            # <=1.2.3
            return lambda v: v <= parse(f"{major}.{minor}.{patch}")

    # Default behavior for partial versions
    if is_partial:
        # For partial versions, we use the standard behavior
        # e.g., "1.2" means >=1.2.0 <1.3.0
        if minor is not None and patch is None:
            # e.g., "1.2" -> >=1.2.0 <1.3.0
            return lambda v: v.major == major and v.minor == minor and v.patch >= 0 and v.patch < 1000000
        elif minor is None:
            # e.g., "1" -> >=1.0.0 <2.0.0
            return lambda v: v.major == major and v.minor == 0 and v.patch == 0
    else:
        # Exact match
        return lambda v: v.major == major and v.minor == minor and v.patch == patch


def _create_comparator_from_range(range_str: str) -> callable:
    """Create a comparator function from a range string."""
    range_str = range_str.strip()

    # Handle hyphen ranges: "1.2.3 - 2.3.4"
    if ' - ' in range_str:
        parts = range_str.split(' - ')
        if len(parts) != 2:
            raise ValueError(f"Invalid hyphen range: {range_str}")

        lower_str = parts[0].strip()
        upper_str = parts[1].strip()

        # Parse lower bound
        lower_op, lower_ver = _parse_version_with_optional_operator(lower_str)
        if lower_op == '':
            lower_op = '>='

        # Parse upper bound
        upper_op, upper_ver = _parse_version_with_optional_operator(upper_str)
        if upper_op == '':
            upper_op = '<='

        # Parse versions
        try:
            lower_version = parse(lower_ver)
        except ValueError:
            raise ValueError(f"Invalid lower bound in hyphen range: {lower_ver}")

        try:
            upper_version = parse(upper_ver)
        except ValueError:
            raise ValueError(f"Invalid upper bound in hyphen range: {upper_ver}")

        # For hyphen ranges, partial upper bound is exclusive of the next
        # e.g., "1.2.3 - 2.3" is >=1.2.3 <2.4.0
        if upper_op == '<=':
            # Increment the next non-partial part
            if upper_version.prerelease is None:
                # For release versions, increment patch
                upper_version = parse(f"{upper_version.major}.{upper_version.minor}.{upper_version.patch + 1}")
                upper_op = '<'
            else:
                # For prerelease versions, we need to handle differently
                # But per spec, we should increment the next non-partial part
                # Since prerelease versions are already parsed, we'll just use the standard behavior
                pass

        return lambda v: v >= lower_version and v < upper_version

    # Handle tilde and caret
    if range_str.startswith('~'):
        version_str = range_str[1:].strip()
        try:
            version = parse(version_str)
        except ValueError:
            raise ValueError(f"Invalid version in tilde range: {version_str}")

        # ~1.2.3 is >=1.2.3 <1.3.0
        # ~1.2 is >=1.2.0 <1.3.0
        # ~1 is >=1.0.0 <2.0.0
        if version.prerelease is None:
            # For release versions
            if version.patch != 0:
                # ~1.2.3 -> >=1.2.3 <1.3.0
                return lambda v: v >= version and v.major == version.major and v.minor == version.minor and v.patch >= 0 and v.patch < 1000000
            elif version.minor != 0:
                # ~1.2 -> >=1.2.0 <1.3.0
                return lambda v: v.major == version.major and v.minor == version.minor and v.patch >= 0 and v.patch < 1000000
            else:
                # ~1 -> >=1.0.0 <2.0.0
                return lambda v: v.major == version.major and v.minor == 0 and v.patch == 0
        else:
            # For prerelease versions, ~1.2.3-alpha.1 is >=1.2.3-alpha.1 <1.3.0
            return lambda v: v >= version and v.major == version.major and v.minor == version.minor and v.patch >= 0 and v.patch < 1000000

    if range_str.startswith('^'):
        version_str = range_str[1:].strip()
        try:
            version = parse(version_str)
        except ValueError:
            raise ValueError(f"Invalid version in caret range: {version_str}")

        # ^1.2.3 is >=1.2.3 <2.0.0
        # ^0.2.3 is >=0.2.3 <0.3.0
        # ^0.0.3 is >=0.0.3 <0.0.4
        # ^1.2.x is >=1.2.0 <2.0.0
        # ^0.0.x is >=0.0.0 <0.1.0
        # ^0.x is >=0.0.0 <1.0.0

        if version.major == 0:
            if version.minor == 0:
                # ^0.0.3 is >=0.0.3 <0.0.4
                return lambda v: v >= version and v.major == 0 and v.minor == 0 and v.patch >= 0 and v.patch < 1000000
            else:
                # ^0.2.3 is >=0.2.3 <0.3.0
                return lambda v: v >= version and v.major == 0 and v.minor == version.minor and v.patch >= 0 and v.patch < 1000000
        else:
            # ^1.2.3 is >=1.2.3 <2.0.0
            return lambda v: v >= version and v.major == version.major and v.minor >= 0 and v.patch >= 0

    # Handle X-ranges and partial versions
