            return v == version
        elif op == '=':
            return v == version
        elif op == '>':
            return v > version
        elif op == '>=':
            return v >= version
        elif op == '<':
            return v < version
        elif op == '<=':
            return v <= version
        else:
            raise ValueError(f"Invalid operator: {op}")

