def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Split a command line into words, implementing a subset of POSIX shell word splitting
    and parameter expansion.
    """
    result = []
    i = 0
    n = len(line)

    # Stack to track quote context: list of ('"' or "'") for nested quotes
    # But we'll handle quotes differently: track current quote context
    # We'll process the line character by character

    # We'll build words incrementally
    current_word = []
    # Track if we're inside double quotes
    in_double_quotes = False
    # Track if we're inside single quotes
    in_single_quotes = False
    # Track if we're inside ${...}
    in_brace_expansion = False
    brace_depth = 0

    # Helper to process a character
    def add_char(c):
        current_word.append(c)

    # Helper to finalize current word
    def finalize_word():
        nonlocal current_word
        if current_word:
            word_str = ''.join(current_word)
            result.append(word_str)
            current_word = []

    # Helper to process parameter expansion
    def process_param_expansion(start_idx):
        """Process ${...} or $NAME starting at start_idx, return the expanded string and new index"""
        nonlocal i
        if i >= n:
            raise ValueError("Trailing $")

        if line[i] != '$':
            raise ValueError("Internal error: process_param_expansion called without $")

        i += 1  # Skip $

        # Check for ${...}
        if i < n and line[i] == '{':
            i += 1  # Skip {
            brace_depth = 1
            start = i
            while i < n and brace_depth > 0:
                if line[i] == '{':
                    brace_depth += 1
                elif line[i] == '}':
                    brace_depth -= 1
                i += 1

            if brace_depth > 0:
                raise ValueError("Unterminated ${")

            # Extract the content inside ${}
            content = line[start:i-1]

            # Parse the content: NAME or NAME:-default or NAME-default
            # Find the first colon or hyphen that's not part of the variable name
            colon_idx = -1
            hyphen_idx = -1

            # Find variable name
            var_name_end = 0
            if content and (content[0].isalpha() or content[0] == '_'):
                var_name_end = 1
                while var_name_end < len(content) and (content[var_name_end].isalnum() or content[var_name_end] == '_'):
                    var_name_end += 1

            var_name = content[:var_name_end]
            rest = content[var_name_end:]

            if rest.startswith(':-'):
                colon_idx = var_name_end
                default_start = var_name_end + 2
                default_text = rest[2:]
            elif rest.startswith('-'):
                hyphen_idx = var_name_end
                default_start = var_name_end + 1
                default_text = rest[1:]
            else:
                default_text = ""

            # Expand the default text if present
            if default_text:
                # We need to expand $ in the default text
